"use strict";(globalThis.webpackChunkdocs=globalThis.webpackChunkdocs||[]).push([[6256],{4664:(n,e,t)=>{t.r(e),t.d(e,{assets:()=>i,contentTitle:()=>l,default:()=>m,frontMatter:()=>r,metadata:()=>s,toc:()=>d});const s=JSON.parse('{"id":"examples/agent-with-tools","title":"\ub3c4\uad6c\ub97c \uc0ac\uc6a9\ud558\ub294 \uc5d0\uc774\uc804\ud2b8","description":"LangGraph\ub85c \uc678\ubd80 \ub3c4\uad6c\ub97c \ud638\ucd9c\ud560 \uc218 \uc788\ub294 ReAct \uc5d0\uc774\uc804\ud2b8\ub97c \ub9cc\ub4e4\uc5b4\ubd05\ub2c8\ub2e4. \uc774 \ud328\ud134\uc740 LLM\uc774 \ud544\uc694\uc5d0 \ub530\ub77c \ub3c4\uad6c\ub97c \uc120\ud0dd\ud558\uace0 \ud638\ucd9c\ud558\ub294 \uac00\uc7a5 \uc77c\ubc18\uc801\uc778 \uc5d0\uc774\uc804\ud2b8 \uad6c\uc870\uc785\ub2c8\ub2e4.","source":"@site/docs/examples/agent-with-tools.md","sourceDirName":"examples","slug":"/examples/agent-with-tools","permalink":"/langgraph/docs/examples/agent-with-tools","draft":false,"unlisted":false,"editUrl":"https://github.com/mypalesong/langgraph/tree/manual/docs/docs/examples/agent-with-tools.md","tags":[],"version":"current","sidebarPosition":2,"frontMatter":{"sidebar_position":2},"sidebar":"tutorialSidebar","previous":{"title":"\uac04\ub2e8\ud55c \ucc57\ubd07 \ub9cc\ub4e4\uae30","permalink":"/langgraph/docs/examples/simple-chatbot"},"next":{"title":"\uba40\ud2f0 \uc5d0\uc774\uc804\ud2b8 \uc2dc\uc2a4\ud15c","permalink":"/langgraph/docs/examples/multi-agent"}}');var a=t(4848),o=t(8453);const r={sidebar_position:2},l="\ub3c4\uad6c\ub97c \uc0ac\uc6a9\ud558\ub294 \uc5d0\uc774\uc804\ud2b8",i={},d=[{value:"ReAct \ud328\ud134 \uc774\ud574\ud558\uae30",id:"react-\ud328\ud134-\uc774\ud574\ud558\uae30",level:2},{value:"\uc644\uc131 \ucf54\ub4dc",id:"\uc644\uc131-\ucf54\ub4dc",level:2},{value:"\ub2e8\uacc4\ubcc4 \uc124\uba85",id:"\ub2e8\uacc4\ubcc4-\uc124\uba85",level:2},{value:"1\ub2e8\uacc4: \ub3c4\uad6c \uc815\uc758\ud558\uae30",id:"1\ub2e8\uacc4-\ub3c4\uad6c-\uc815\uc758\ud558\uae30",level:3},{value:"2\ub2e8\uacc4: \ucee4\uc2a4\ud140 Tool \ub178\ub4dc",id:"2\ub2e8\uacc4-\ucee4\uc2a4\ud140-tool-\ub178\ub4dc",level:3},{value:"3\ub2e8\uacc4: \ubc18\ubcf5 \uc81c\ud55c \ucd94\uac00",id:"3\ub2e8\uacc4-\ubc18\ubcf5-\uc81c\ud55c-\ucd94\uac00",level:3},{value:"\uc804\uccb4 \uac1c\uc120\ub41c \ubc84\uc804",id:"\uc804\uccb4-\uac1c\uc120\ub41c-\ubc84\uc804",level:2},{value:"\uc2e4\ud589 \uacb0\uacfc \uc608\uc2dc",id:"\uc2e4\ud589-\uacb0\uacfc-\uc608\uc2dc",level:2},{value:"\ub2e4\uc74c \ub2e8\uacc4",id:"\ub2e4\uc74c-\ub2e8\uacc4",level:2}];function c(n){const e={a:"a",code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",mermaid:"mermaid",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,o.R)(),...n.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(e.header,{children:(0,a.jsx)(e.h1,{id:"\ub3c4\uad6c\ub97c-\uc0ac\uc6a9\ud558\ub294-\uc5d0\uc774\uc804\ud2b8",children:"\ub3c4\uad6c\ub97c \uc0ac\uc6a9\ud558\ub294 \uc5d0\uc774\uc804\ud2b8"})}),"\n",(0,a.jsxs)(e.p,{children:["LangGraph\ub85c ",(0,a.jsx)(e.strong,{children:"\uc678\ubd80 \ub3c4\uad6c\ub97c \ud638\ucd9c\ud560 \uc218 \uc788\ub294 ReAct \uc5d0\uc774\uc804\ud2b8"}),"\ub97c \ub9cc\ub4e4\uc5b4\ubd05\ub2c8\ub2e4. \uc774 \ud328\ud134\uc740 LLM\uc774 \ud544\uc694\uc5d0 \ub530\ub77c \ub3c4\uad6c\ub97c \uc120\ud0dd\ud558\uace0 \ud638\ucd9c\ud558\ub294 \uac00\uc7a5 \uc77c\ubc18\uc801\uc778 \uc5d0\uc774\uc804\ud2b8 \uad6c\uc870\uc785\ub2c8\ub2e4."]}),"\n",(0,a.jsx)(e.h2,{id:"react-\ud328\ud134-\uc774\ud574\ud558\uae30",children:"ReAct \ud328\ud134 \uc774\ud574\ud558\uae30"}),"\n",(0,a.jsx)(e.mermaid,{value:'flowchart TD\n    subgraph ReAct["ReAct \uc5d0\uc774\uc804\ud2b8"]\n        LLM[LLM] --\x3e|tool_calls?| Tools[Tools]\n        Tools --\x3e|results| LLM\n        LLM --\x3e|No tool_calls| END((END))\n    end'}),"\n",(0,a.jsx)(e.h2,{id:"\uc644\uc131-\ucf54\ub4dc",children:"\uc644\uc131 \ucf54\ub4dc"}),"\n",(0,a.jsx)(e.pre,{children:(0,a.jsx)(e.code,{className:"language-python",children:'from typing import Annotated, Literal\nfrom langchain_openai import ChatOpenAI\nfrom langchain_core.messages import BaseMessage, HumanMessage, AIMessage, ToolMessage\nfrom langchain_core.tools import tool\nfrom langgraph.graph import StateGraph, MessagesState, START, END\nfrom langgraph.checkpoint.memory import MemorySaver\nfrom langgraph.prebuilt import ToolNode\n\n# 1. \ub3c4\uad6c \uc815\uc758\n@tool\ndef get_weather(city: str) -> str:\n    """\uc9c0\uc815\ub41c \ub3c4\uc2dc\uc758 \ud604\uc7ac \ub0a0\uc528\ub97c \uc870\ud68c\ud569\ub2c8\ub2e4."""\n    # \uc2e4\uc81c\ub85c\ub294 \ub0a0\uc528 API \ud638\ucd9c\n    weather_data = {\n        "\uc11c\uc6b8": "\ub9d1\uc74c, 15\xb0C",\n        "\ubd80\uc0b0": "\ud750\ub9bc, 18\xb0C",\n        "\uc81c\uc8fc": "\ube44, 20\xb0C",\n    }\n    return weather_data.get(city, f"{city}\uc758 \ub0a0\uc528 \uc815\ubcf4\ub97c \ucc3e\uc744 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.")\n\n@tool\ndef calculate(expression: str) -> str:\n    """\uc218\ud559 \ud45c\ud604\uc2dd\uc744 \uacc4\uc0b0\ud569\ub2c8\ub2e4. \uc608: \'2 + 3 * 4\'"""\n    try:\n        result = eval(expression)\n        return f"{expression} = {result}"\n    except Exception as e:\n        return f"\uacc4\uc0b0 \uc624\ub958: {str(e)}"\n\n@tool\ndef search_web(query: str) -> str:\n    """\uc6f9\uc5d0\uc11c \uc815\ubcf4\ub97c \uac80\uc0c9\ud569\ub2c8\ub2e4."""\n    # \uc2e4\uc81c\ub85c\ub294 \uac80\uc0c9 API \ud638\ucd9c\n    return f"\'{query}\'\uc5d0 \ub300\ud55c \uac80\uc0c9 \uacb0\uacfc: \uad00\ub828 \uc815\ubcf4\ub97c \ucc3e\uc558\uc2b5\ub2c8\ub2e4."\n\n# 2. \ub3c4\uad6c \ubaa9\ub85d\uacfc LLM \uc124\uc815\ntools = [get_weather, calculate, search_web]\nllm = ChatOpenAI(model="gpt-4o-mini", temperature=0).bind_tools(tools)\n\n# 3. \ub178\ub4dc \ud568\uc218 \uc815\uc758\ndef call_model(state: MessagesState) -> dict:\n    """LLM\uc744 \ud638\ucd9c\ud558\uc5ec \uc751\ub2f5 \uc0dd\uc131"""\n    response = llm.invoke(state["messages"])\n    return {"messages": [response]}\n\n# 4. \ub77c\uc6b0\ud130 \ud568\uc218\ndef should_continue(state: MessagesState) -> Literal["tools", "__end__"]:\n    """\ub3c4\uad6c \ud638\ucd9c\uc774 \ud544\uc694\ud55c\uc9c0 \uacb0\uc815"""\n    last_message = state["messages"][-1]\n\n    if isinstance(last_message, AIMessage) and last_message.tool_calls:\n        return "tools"\n    return "__end__"\n\n# 5. \uadf8\ub798\ud504 \uad6c\uc131\ngraph = StateGraph(MessagesState)\n\n# \ub178\ub4dc \ucd94\uac00\ngraph.add_node("agent", call_model)\ngraph.add_node("tools", ToolNode(tools))  # LangGraph \ub0b4\uc7a5 ToolNode \uc0ac\uc6a9\n\n# \uc5e3\uc9c0 \ucd94\uac00\ngraph.add_edge(START, "agent")\ngraph.add_conditional_edges(\n    "agent",\n    should_continue,\n    {"tools": "tools", "__end__": END}\n)\ngraph.add_edge("tools", "agent")  # \ub3c4\uad6c \uc2e4\ud589 \ud6c4 \ub2e4\uc2dc \uc5d0\uc774\uc804\ud2b8\ub85c\n\n# 6. \ucef4\ud30c\uc77c\nmemory = MemorySaver()\napp = graph.compile(checkpointer=memory)\n\n# 7. \uc2e4\ud589 \ud568\uc218\ndef run_agent(query: str, thread_id: str = "default"):\n    config = {"configurable": {"thread_id": thread_id}}\n    result = app.invoke(\n        {"messages": [HumanMessage(content=query)]},\n        config\n    )\n    return result["messages"][-1].content\n\n# \uc2e4\ud589 \uc608\uc2dc\nprint(run_agent("\uc11c\uc6b8 \ub0a0\uc528 \uc5b4\ub54c?"))\nprint(run_agent("15 * 24 + 100 \uacc4\uc0b0\ud574\uc918"))\n'})}),"\n",(0,a.jsx)(e.h2,{id:"\ub2e8\uacc4\ubcc4-\uc124\uba85",children:"\ub2e8\uacc4\ubcc4 \uc124\uba85"}),"\n",(0,a.jsx)(e.h3,{id:"1\ub2e8\uacc4-\ub3c4\uad6c-\uc815\uc758\ud558\uae30",children:"1\ub2e8\uacc4: \ub3c4\uad6c \uc815\uc758\ud558\uae30"}),"\n",(0,a.jsxs)(e.p,{children:[(0,a.jsx)(e.code,{children:"@tool"})," \ub370\ucf54\ub808\uc774\ud130\ub85c LLM\uc774 \ud638\ucd9c\ud560 \uc218 \uc788\ub294 \ub3c4\uad6c\ub97c \uc815\uc758\ud569\ub2c8\ub2e4:"]}),"\n",(0,a.jsx)(e.pre,{children:(0,a.jsx)(e.code,{className:"language-python",children:'from langchain_core.tools import tool\nfrom pydantic import BaseModel, Field\n\n# \ubc29\ubc95 1: \uac04\ub2e8\ud55c \ub3c4\uad6c\n@tool\ndef simple_tool(input: str) -> str:\n    """\ub3c4\uad6c \uc124\uba85 (LLM\uc774 \uc774 \uc124\uba85\uc744 \ubcf4\uace0 \ub3c4\uad6c \uc120\ud0dd)"""\n    return f"\uacb0\uacfc: {input}"\n\n# \ubc29\ubc95 2: \ubcf5\uc7a1\ud55c \uc785\ub825 \uc2a4\ud0a4\ub9c8\nclass SearchInput(BaseModel):\n    query: str = Field(description="\uac80\uc0c9\ud560 \ucffc\ub9ac")\n    max_results: int = Field(default=5, description="\ucd5c\ub300 \uacb0\uacfc \uc218")\n\n@tool(args_schema=SearchInput)\ndef advanced_search(query: str, max_results: int) -> str:\n    """\uace0\uae09 \uac80\uc0c9\uc744 \uc218\ud589\ud569\ub2c8\ub2e4."""\n    return f"\'{query}\'\ub85c {max_results}\uac1c \uacb0\uacfc \uac80\uc0c9"\n'})}),"\n",(0,a.jsx)(e.h3,{id:"2\ub2e8\uacc4-\ucee4\uc2a4\ud140-tool-\ub178\ub4dc",children:"2\ub2e8\uacc4: \ucee4\uc2a4\ud140 Tool \ub178\ub4dc"}),"\n",(0,a.jsx)(e.p,{children:"ToolNode \ub300\uc2e0 \uc9c1\uc811 \uad6c\ud604\ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4:"}),"\n",(0,a.jsx)(e.pre,{children:(0,a.jsx)(e.code,{className:"language-python",children:'def custom_tool_node(state: MessagesState) -> dict:\n    """\ub3c4\uad6c \ud638\ucd9c\uc744 \uc9c1\uc811 \ucc98\ub9ac"""\n    last_message = state["messages"][-1]\n    tool_results = []\n\n    # \ub3c4\uad6c \ub9e4\ud551\n    tool_map = {\n        "get_weather": get_weather,\n        "calculate": calculate,\n        "search_web": search_web,\n    }\n\n    for tool_call in last_message.tool_calls:\n        tool_name = tool_call["name"]\n        tool_args = tool_call["args"]\n\n        # \ub3c4\uad6c \uc2e4\ud589\n        tool_fn = tool_map.get(tool_name)\n        if tool_fn:\n            result = tool_fn.invoke(tool_args)\n        else:\n            result = f"\uc54c \uc218 \uc5c6\ub294 \ub3c4\uad6c: {tool_name}"\n\n        # ToolMessage\ub85c \uacb0\uacfc \ubc18\ud658\n        tool_results.append(\n            ToolMessage(\n                content=str(result),\n                tool_call_id=tool_call["id"]\n            )\n        )\n\n    return {"messages": tool_results}\n'})}),"\n",(0,a.jsx)(e.h3,{id:"3\ub2e8\uacc4-\ubc18\ubcf5-\uc81c\ud55c-\ucd94\uac00",children:"3\ub2e8\uacc4: \ubc18\ubcf5 \uc81c\ud55c \ucd94\uac00"}),"\n",(0,a.jsx)(e.p,{children:"\ubb34\ud55c \ub8e8\ud504\ub97c \ubc29\uc9c0\ud558\uae30 \uc704\ud574 \ubc18\ubcf5 \ud69f\uc218\ub97c \uc81c\ud55c\ud569\ub2c8\ub2e4:"}),"\n",(0,a.jsx)(e.pre,{children:(0,a.jsx)(e.code,{className:"language-python",children:'class AgentState(MessagesState):\n    iteration: int\n\ndef call_model_with_limit(state: AgentState) -> dict:\n    response = llm.invoke(state["messages"])\n    return {\n        "messages": [response],\n        "iteration": state["iteration"] + 1\n    }\n\ndef should_continue_with_limit(state: AgentState) -> Literal["tools", "__end__"]:\n    # \ubc18\ubcf5 \uc81c\ud55c \uccb4\ud06c\n    if state["iteration"] >= 10:\n        return "__end__"\n\n    last_message = state["messages"][-1]\n    if isinstance(last_message, AIMessage) and last_message.tool_calls:\n        return "tools"\n    return "__end__"\n'})}),"\n",(0,a.jsx)(e.h2,{id:"\uc804\uccb4-\uac1c\uc120\ub41c-\ubc84\uc804",children:"\uc804\uccb4 \uac1c\uc120\ub41c \ubc84\uc804"}),"\n",(0,a.jsx)(e.pre,{children:(0,a.jsx)(e.code,{className:"language-python",children:'from typing import Annotated, Literal, TypedDict\nfrom langchain_openai import ChatOpenAI\nfrom langchain_core.messages import (\n    BaseMessage, HumanMessage, AIMessage, ToolMessage, SystemMessage\n)\nfrom langchain_core.tools import tool\nfrom langgraph.graph import StateGraph, MessagesState, START, END\nfrom langgraph.checkpoint.memory import MemorySaver\nfrom langgraph.prebuilt import ToolNode\nimport json\nfrom datetime import datetime\n\n# === \ub3c4\uad6c \uc815\uc758 ===\n\n@tool\ndef get_weather(city: str) -> str:\n    """\ub3c4\uc2dc\uc758 \ud604\uc7ac \ub0a0\uc528\ub97c \uc870\ud68c\ud569\ub2c8\ub2e4."""\n    weather_db = {\n        "\uc11c\uc6b8": {"temp": 15, "condition": "\ub9d1\uc74c", "humidity": 45},\n        "\ubd80\uc0b0": {"temp": 18, "condition": "\ud750\ub9bc", "humidity": 60},\n        "\uc81c\uc8fc": {"temp": 20, "condition": "\ube44", "humidity": 80},\n        "\ub300\uc804": {"temp": 14, "condition": "\ub9d1\uc74c", "humidity": 50},\n    }\n    data = weather_db.get(city)\n    if data:\n        return f"{city}: {data[\'condition\']}, {data[\'temp\']}\xb0C, \uc2b5\ub3c4 {data[\'humidity\']}%"\n    return f"{city}\uc758 \ub0a0\uc528 \uc815\ubcf4\ub97c \ucc3e\uc744 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4."\n\n@tool\ndef calculate(expression: str) -> str:\n    """\uc218\ud559 \ud45c\ud604\uc2dd\uc744 \uacc4\uc0b0\ud569\ub2c8\ub2e4. \uc608: \'2 + 3 * 4\', \'sqrt(16)\', \'pow(2, 10)\'"""\n    import math\n    try:\n        # \uc548\uc804\ud55c \ud3c9\uac00\ub97c \uc704\ud55c \uc81c\ud55c\ub41c \ucee8\ud14d\uc2a4\ud2b8\n        safe_dict = {\n            "sqrt": math.sqrt,\n            "pow": pow,\n            "abs": abs,\n            "round": round,\n            "sin": math.sin,\n            "cos": math.cos,\n            "pi": math.pi,\n        }\n        result = eval(expression, {"__builtins__": {}}, safe_dict)\n        return f"{expression} = {result}"\n    except Exception as e:\n        return f"\uacc4\uc0b0 \uc624\ub958: {str(e)}"\n\n@tool\ndef get_current_time() -> str:\n    """\ud604\uc7ac \ub0a0\uc9dc\uc640 \uc2dc\uac04\uc744 \ubc18\ud658\ud569\ub2c8\ub2e4."""\n    now = datetime.now()\n    return now.strftime("%Y\ub144 %m\uc6d4 %d\uc77c %H\uc2dc %M\ubd84")\n\n@tool\ndef unit_convert(value: float, from_unit: str, to_unit: str) -> str:\n    """\ub2e8\uc704\ub97c \ubcc0\ud658\ud569\ub2c8\ub2e4. \uc9c0\uc6d0: km/m, kg/g, celsius/fahrenheit"""\n    conversions = {\n        ("km", "m"): lambda x: x * 1000,\n        ("m", "km"): lambda x: x / 1000,\n        ("kg", "g"): lambda x: x * 1000,\n        ("g", "kg"): lambda x: x / 1000,\n        ("celsius", "fahrenheit"): lambda x: x * 9/5 + 32,\n        ("fahrenheit", "celsius"): lambda x: (x - 32) * 5/9,\n    }\n    key = (from_unit.lower(), to_unit.lower())\n    if key in conversions:\n        result = conversions[key](value)\n        return f"{value} {from_unit} = {result:.2f} {to_unit}"\n    return f"\uc9c0\uc6d0\ud558\uc9c0 \uc54a\ub294 \ubcc0\ud658: {from_unit} -> {to_unit}"\n\n# === \uc5d0\uc774\uc804\ud2b8 \uad6c\uc131 ===\n\ntools = [get_weather, calculate, get_current_time, unit_convert]\ntool_node = ToolNode(tools)\n\n# \uc2dc\uc2a4\ud15c \ud504\ub86c\ud504\ud2b8\nSYSTEM_PROMPT = """\ub2f9\uc2e0\uc740 \ub2e4\uc591\ud55c \ub3c4\uad6c\ub97c \ud65c\uc6a9\ud560 \uc218 \uc788\ub294 AI \uc5b4\uc2dc\uc2a4\ud134\ud2b8\uc785\ub2c8\ub2e4.\n\n\uc0ac\uc6a9 \uac00\ub2a5\ud55c \ub3c4\uad6c:\n- get_weather: \ub3c4\uc2dc\uc758 \ub0a0\uc528 \uc870\ud68c\n- calculate: \uc218\ud559 \uacc4\uc0b0\n- get_current_time: \ud604\uc7ac \uc2dc\uac04 \uc870\ud68c\n- unit_convert: \ub2e8\uc704 \ubcc0\ud658\n\n\uaddc\uce59:\n1. \ud544\uc694\ud55c \uacbd\uc6b0\uc5d0\ub9cc \ub3c4\uad6c\ub97c \uc0ac\uc6a9\ud558\uc138\uc694\n2. \ub3c4\uad6c \uacb0\uacfc\ub97c \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc124\uba85\ud574\uc8fc\uc138\uc694\n3. \ud55c\uad6d\uc5b4\ub85c \uc751\ub2f5\ud558\uc138\uc694\n4. \ub3c4\uad6c\ub85c \ud574\uacb0\ud560 \uc218 \uc5c6\ub294 \uc9c8\ubb38\uc740 \uc9c1\uc811 \ub2f5\ubcc0\ud558\uc138\uc694"""\n\nllm = ChatOpenAI(model="gpt-4o-mini", temperature=0).bind_tools(tools)\n\n# State \uc815\uc758\nclass AgentState(MessagesState):\n    iteration: int\n\ndef call_agent(state: AgentState) -> dict:\n    """\uc5d0\uc774\uc804\ud2b8(LLM) \ud638\ucd9c"""\n    # \uccab \ud638\ucd9c\uc2dc \uc2dc\uc2a4\ud15c \ud504\ub86c\ud504\ud2b8 \ucd94\uac00\n    messages = state["messages"]\n    if not any(isinstance(m, SystemMessage) for m in messages):\n        messages = [SystemMessage(content=SYSTEM_PROMPT)] + messages\n\n    response = llm.invoke(messages)\n    return {\n        "messages": [response],\n        "iteration": state["iteration"] + 1\n    }\n\ndef should_continue(state: AgentState) -> Literal["tools", "end"]:\n    """\ub2e4\uc74c \ub2e8\uacc4 \uacb0\uc815"""\n    # \ubc18\ubcf5 \uc81c\ud55c\n    if state["iteration"] >= 10:\n        return "end"\n\n    last_message = state["messages"][-1]\n    if isinstance(last_message, AIMessage) and last_message.tool_calls:\n        return "tools"\n    return "end"\n\n# \uadf8\ub798\ud504 \uad6c\uc131\ngraph = StateGraph(AgentState)\n\ngraph.add_node("agent", call_agent)\ngraph.add_node("tools", tool_node)\n\ngraph.add_edge(START, "agent")\ngraph.add_conditional_edges(\n    "agent",\n    should_continue,\n    {"tools": "tools", "end": END}\n)\ngraph.add_edge("tools", "agent")\n\n# \ucef4\ud30c\uc77c\nmemory = MemorySaver()\napp = graph.compile(checkpointer=memory)\n\n# === \uc2e4\ud589 \uc778\ud130\ud398\uc774\uc2a4 ===\n\ndef run_agent(query: str, thread_id: str = "default", verbose: bool = False):\n    """\uc5d0\uc774\uc804\ud2b8 \uc2e4\ud589"""\n    config = {"configurable": {"thread_id": thread_id}}\n\n    if verbose:\n        print(f"\\n\uc9c8\ubb38: {query}")\n        print("-" * 40)\n\n        # \uc2a4\ud2b8\ub9ac\ubc0d\uc73c\ub85c \uacfc\uc815 \ucd9c\ub825\n        for event in app.stream(\n            {"messages": [HumanMessage(content=query)], "iteration": 0},\n            config,\n            stream_mode="updates"\n        ):\n            for node, update in event.items():\n                if node == "agent":\n                    msg = update["messages"][0]\n                    if msg.tool_calls:\n                        for tc in msg.tool_calls:\n                            print(f"[\ub3c4\uad6c \ud638\ucd9c] {tc[\'name\']}: {tc[\'args\']}")\n                elif node == "tools":\n                    for msg in update["messages"]:\n                        print(f"[\ub3c4\uad6c \uacb0\uacfc] {msg.content[:100]}...")\n\n        print("-" * 40)\n        state = app.get_state(config)\n        return state.values["messages"][-1].content\n    else:\n        result = app.invoke(\n            {"messages": [HumanMessage(content=query)], "iteration": 0},\n            config\n        )\n        return result["messages"][-1].content\n\n# === \ud14c\uc2a4\ud2b8 ===\n\nif __name__ == "__main__":\n    print("=== \ub2e4\uae30\ub2a5 AI \uc5d0\uc774\uc804\ud2b8 ===\\n")\n\n    # \ud14c\uc2a4\ud2b8 \ucffc\ub9ac\ub4e4\n    queries = [\n        "\uc11c\uc6b8\uacfc \ubd80\uc0b0 \ub0a0\uc528\ub97c \ube44\uad50\ud574\uc918",\n        "123 * 456 + 789 \uacc4\uc0b0\ud574\uc918",\n        "\uc9c0\uae08 \uba87 \uc2dc\uc57c?",\n        "100km\ub97c m\ub85c \ubcc0\ud658\ud574\uc918",\n        "\uc12d\uc528 30\ub3c4\ub97c \ud654\uc528\ub85c \ubc14\uafb8\uba74?",\n    ]\n\n    for query in queries:\n        print(f"Q: {query}")\n        answer = run_agent(query, verbose=True)\n        print(f"A: {answer}\\n")\n        print("=" * 50 + "\\n")\n'})}),"\n",(0,a.jsx)(e.h2,{id:"\uc2e4\ud589-\uacb0\uacfc-\uc608\uc2dc",children:"\uc2e4\ud589 \uacb0\uacfc \uc608\uc2dc"}),"\n",(0,a.jsx)(e.pre,{children:(0,a.jsx)(e.code,{children:"=== \ub2e4\uae30\ub2a5 AI \uc5d0\uc774\uc804\ud2b8 ===\n\nQ: \uc11c\uc6b8\uacfc \ubd80\uc0b0 \ub0a0\uc528\ub97c \ube44\uad50\ud574\uc918\n----------------------------------------\n[\ub3c4\uad6c \ud638\ucd9c] get_weather: {'city': '\uc11c\uc6b8'}\n[\ub3c4\uad6c \ud638\ucd9c] get_weather: {'city': '\ubd80\uc0b0'}\n[\ub3c4\uad6c \uacb0\uacfc] \uc11c\uc6b8: \ub9d1\uc74c, 15\xb0C, \uc2b5\ub3c4 45%...\n[\ub3c4\uad6c \uacb0\uacfc] \ubd80\uc0b0: \ud750\ub9bc, 18\xb0C, \uc2b5\ub3c4 60%...\n----------------------------------------\nA: \uc11c\uc6b8\uacfc \ubd80\uc0b0\uc758 \ub0a0\uc528\ub97c \ube44\uad50\ud574 \ub4dc\ub9b4\uac8c\uc694:\n\n**\uc11c\uc6b8**: \ub9d1\uc74c, 15\xb0C, \uc2b5\ub3c4 45%\n**\ubd80\uc0b0**: \ud750\ub9bc, 18\xb0C, \uc2b5\ub3c4 60%\n\n\ubd80\uc0b0\uc774 \uc11c\uc6b8\ubcf4\ub2e4 3\ub3c4 \uc815\ub3c4 \ub530\ub73b\ud558\uc9c0\ub9cc, \uad6c\ub984\uc774 \uc788\uc5b4\uc694.\n\uc11c\uc6b8\uc740 \ub9d1\uace0 \uac74\uc870\ud55c \ud3b8\uc774\uc5d0\uc694.\n\n==================================================\n\nQ: 123 * 456 + 789 \uacc4\uc0b0\ud574\uc918\n----------------------------------------\n[\ub3c4\uad6c \ud638\ucd9c] calculate: {'expression': '123 * 456 + 789'}\n[\ub3c4\uad6c \uacb0\uacfc] 123 * 456 + 789 = 56877...\n----------------------------------------\nA: \uacc4\uc0b0 \uacb0\uacfc\ub294 **56,877**\uc785\ub2c8\ub2e4.\n\n(123 \xd7 456 = 56,088, 56,088 + 789 = 56,877)\n"})}),"\n",(0,a.jsx)(e.h2,{id:"\ub2e4\uc74c-\ub2e8\uacc4",children:"\ub2e4\uc74c \ub2e8\uacc4"}),"\n",(0,a.jsxs)(e.ul,{children:["\n",(0,a.jsxs)(e.li,{children:[(0,a.jsx)(e.a,{href:"/docs/advanced/human-in-the-loop",children:"Human-in-the-Loop"})," - \ub3c4\uad6c \ud638\ucd9c \uc804 \uc0ac\ub78c \uc2b9\uc778"]}),"\n",(0,a.jsxs)(e.li,{children:[(0,a.jsx)(e.a,{href:"/docs/advanced/streaming",children:"\uc2a4\ud2b8\ub9ac\ubc0d"})," - \uc2e4\uc2dc\uac04 \ub3c4\uad6c \uc2e4\ud589 \ubaa8\ub2c8\ud130\ub9c1"]}),"\n",(0,a.jsxs)(e.li,{children:[(0,a.jsx)(e.a,{href:"/docs/advanced/checkpointing",children:"\uccb4\ud06c\ud3ec\uc778\ud305"})," - \uc5d0\uc774\uc804\ud2b8 \uc0c1\ud0dc \uc800\uc7a5"]}),"\n"]})]})}function m(n={}){const{wrapper:e}={...(0,o.R)(),...n.components};return e?(0,a.jsx)(e,{...n,children:(0,a.jsx)(c,{...n})}):c(n)}}}]);